import{_ as o,o as a,c as e,ai as r}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"网站总拦 Bot、一直超时？先试这两个设置","description":"","frontmatter":{"date":"2026-10-20T00:00:00.000Z","title":"网站总拦 Bot、一直超时？先试这两个设置","summary":"有些网站会拦截云电脑的访问，重置电脑也没用。真正有效的是「通过这台电脑转发流量」和「在这台电脑上执行」两个开关。","category":"使用技巧","tags":["云电脑","故障排查","网络"],"sources":[{"url":"https://cursor.com/help/grok-bot/faqs","author":"Grok Bot FAQs","platform":"官方帮助中心"},{"url":"https://docs.x.ai/grok-bot/faq","author":"Grok Bot FAQ","platform":"官方文档"}],"updates":[{"link":"/basics/cloud-computer","title":"云电脑怎么用"}],"wordCount":481,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"网站总拦 Bot、一直超时？先试这两个设置 | WANGXXXL"}],["meta",{"property":"og:description","content":"有些网站会拦截云电脑的访问，重置电脑也没用。真正有效的是「通过这台电脑转发流量」和「在这台电脑上执行」两个开关。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-site-blocks-bot"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-site-blocks-bot-186091c9b3.png"}],["meta",{"property":"og:image:alt","content":"网站总拦 Bot、一直超时？先试这两个设置 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"网站总拦 Bot、一直超时？先试这两个设置 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"有些网站会拦截云电脑的访问，重置电脑也没用。真正有效的是「通过这台电脑转发流量」和「在这台电脑上执行」两个开关。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-site-blocks-bot-186091c9b3.png"}],["meta",{"name":"twitter:image:alt","content":"网站总拦 Bot、一直超时？先试这两个设置 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-site-blocks-bot"}]]},"headers":[],"relativePath":"daily/2026-10-20-site-blocks-bot.md","filePath":"daily/2026-10-20-site-blocks-bot.md","lastUpdated":1792499451000}'),n={name:"daily/2026-10-20-site-blocks-bot.md"};function s(i,t,l,c,p,d){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="网站总拦-bot、一直超时-先试这两个设置" tabindex="-1">网站总拦 Bot、一直超时？先试这两个设置 <a class="header-anchor" href="#网站总拦-bot、一直超时-先试这两个设置" aria-label="Permalink to &quot;网站总拦 Bot、一直超时？先试这两个设置&quot;">​</a></h1><p><strong>症状</strong>：同一个网址，你自己电脑上打得开，Bot 打开却一直转圈、报安全连接错误、弹验证码，或者干脆说超时。</p><p><strong>原因</strong>：Bot 的云电脑通过共享网络上网，有些网站会直接拒绝这类来源的连接。官方帮助中心说得很明确：这种情况下 <strong>更新、恢复、重置云电脑都没用</strong>，别在这上面浪费时间。</p><h2 id="办法一-通过你的电脑转发流量" tabindex="-1">办法一：通过你的电脑转发流量 <a class="header-anchor" href="#办法一-通过你的电脑转发流量" aria-label="Permalink to &quot;办法一：通过你的电脑转发流量&quot;">​</a></h2><p>打开 <strong>设置 → 电脑（Computer）→ 你的电脑（Your computer）</strong>，打开 <strong>Route traffic through this computer</strong>（通过这台电脑转发流量）。</p><ul><li>打开后，Bot 浏览器的新连接会走你桌面电脑的网络，网站看到的是你的网络和 IP。</li><li><strong>前提</strong>：Grok Bot 桌面端要开着。如果提示先更新 Bot 的电脑，点更新即可。</li><li>团队账号如果被管理员关掉了这个功能，开关会是锁定状态。</li></ul><h2 id="办法二-让-bot-在你的电脑上执行" tabindex="-1">办法二：让 Bot 在你的电脑上执行 <a class="header-anchor" href="#办法二-让-bot-在你的电脑上执行" aria-label="Permalink to &quot;办法二：让 Bot 在你的电脑上执行&quot;">​</a></h2><p>同一页里的 <strong>Execution on this computer</strong>（在这台电脑上执行），选「每次询问」或「始终允许」。这样 Bot 的命令和脚本（包括 API 调用）会在你的桌面电脑上跑，而不是云电脑。</p><p>适合：调用只允许特定网络访问的接口、公司内网工具。更稳妥的设置方法见<a href="/basics/local-computer">在自己电脑上干活</a>。</p><h2 id="遇到验证码或重新登录" tabindex="-1">遇到验证码或重新登录 <a class="header-anchor" href="#遇到验证码或重新登录" aria-label="Permalink to &quot;遇到验证码或重新登录&quot;">​</a></h2><p>这是网站在确认&quot;是不是真人&quot;，<strong>不要让 Bot 想办法绕过</strong>。让它停下来交给你：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果遇到验证码、登录页或二次验证，停在那一步，截图告诉我卡在哪，</span></span>
<span class="line"><span>等我接管完成后你再继续，不要尝试绕过。</span></span></code></pre></div><h2 id="两个都不行怎么办" tabindex="-1">两个都不行怎么办 <a class="header-anchor" href="#两个都不行怎么办" aria-label="Permalink to &quot;两个都不行怎么办&quot;">​</a></h2><p>带上网址和报错截图联系官方支持，他们可以查 Bot 的电脑能不能访问这个站点。联系时附上版本信息（账户菜单 → Support → About → Copy version info）和请求 ID（右键那条消息 → Copy request ID），处理会快很多。</p>`,14)])])}const g=o(n,[["render",s]]);export{h as __pageData,g as default};
